    var i=band(s,[[1,"Score 1, mortality about 0 percent at 6 months. Favourable. Routine intensive care."],[2,"Score 2, mortality about 7 percent at 6 months. Observe closely."],[3,"Score 3, mortality about 16 percent at 6 months. Intensive care and frequent reassessment."],[4,"Score 4, mortality about 26 percent at 6 months. High risk. Consider intracranial pressure management."],[5,"Score 5, mortality about 53 percent at 6 months. Very high risk. Neurosurgical and critical care escalation."],[6,"Score 6, mortality about 61 percent at 6 months. Highest risk. Maximal therapy and family discussion."]]);
